Mesh<Point, double> walls;
    auto faces = rt.power_diagram_faces();

    for (auto face_it = faces.begin(); face_it != faces.end(); ++face_it) {
        if (face_it->is_infinite()) continue;

        // Get the three vertices of the face
        auto v0 = face_it->vertex(0);
        auto v1 = face_it->vertex(1);
        auto v2 = face_it->vertex(2);

        // Get the dual power cell edges
        auto edge0 = face_it->dual();
        auto edge1 = rt.mirror_edge(face_it, 1).dual();
        auto edge2 = rt.mirror_edge(face_it, 2).dual();

        // Check if any edge length exceeds the threshold
        bool is_wall = false;
        if (!edge0.is_infinite() && edge0.squared_length() > threshold * threshold) is_wall = true;
        if (!edge1.is_infinite() && edge1.squared_length() > threshold * threshold) is_wall = true;
        if (!edge2.is_infinite() && edge2.squared_length() > threshold * threshold) is_wall = true;

        if (is_wall) {
            // Add the face to the wall mesh
            walls.add_face(
                Point(v0->point().x(), v0->point().y(), v0->point().z()),
                Point(v1->point().x(), v1->point().y(), v1->point().z()),
                Point(v2->point().x(), v2->point().y(), v2->point().z())
            );
        }
    }

    return walls;
    // END_CODE

